<script setup lang="ts">
import { ref, watch } from "vue";
import { ApiError, item, request, query, type SchedulePolicy, type AutomationSchedule, type AutomationRevision, type Page } from "@papilio/api";
import { useAuth } from "@papilio/auth";
import { faDate, faNumber } from "@papilio/ui";
import NumField from "@papilio/ui/NumField.vue";
const props = defineProps<{ schedule: AutomationSchedule; title: string }>();
const emit = defineEmits<{ changed: [AutomationSchedule] }>();
const auth = useAuth(); const current = ref<AutomationSchedule|null>(null); const draft = ref<SchedulePolicy|null>(null);
const interval = ref(""); const batch = ref(""); const recheck = ref(""); const reason = ref(""); const busy = ref(false); const error = ref(""); const notice = ref("");
const history = ref<AutomationRevision[]>([]); const historyState = ref<"loading"|"ready"|"error">("loading"); const page = ref(1); const pages = ref(1); let version = 0;
function values(row: AutomationSchedule): SchedulePolicy { return { mode: row.mode, interval_seconds: row.interval_seconds, enabled: row.enabled, cron: row.cron, timezone: row.timezone, batch_size: row.batch_size, recheck_seconds: row.recheck_seconds }; }
function reset(row: AutomationSchedule): void { current.value = row; draft.value = values(row); interval.value = row.interval_seconds === null ? "" : String(row.interval_seconds); batch.value = String(row.batch_size); recheck.value = row.recheck_seconds === null ? "" : String(row.recheck_seconds); }
async function loadHistory(): Promise<void> { const key = props.schedule.key; const generation = version; const selectedPage = page.value; historyState.value = "loading"; try { const result = await request<Page<AutomationRevision>>(`/v1/admin/automation/schedules/${key}/history?${query({page: selectedPage})}`); if (generation !== version || page.value !== selectedPage) return; history.value = result.data; pages.value = result.meta.pager?.total_pages ?? 1; historyState.value = "ready"; } catch(cause) { if (generation !== version) return; historyState.value = "error"; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } }
watch(() => props.schedule.key, () => { version++; reset(props.schedule); reason.value = ""; error.value = ""; notice.value = ""; page.value = 1; history.value = []; void loadHistory(); }, {immediate: true});
async function reload(): Promise<void> { const key = props.schedule.key; const generation = version; busy.value = true; error.value = ""; try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`); if (generation !== version) return; reset(row); emit("changed", row); await loadHistory(); } catch(cause) { if (generation === version) error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value = false; } }
async function save(): Promise<void> {
 if (!current.value || !draft.value || busy.value) return; const key = current.value.key; const generation = version; busy.value = true; error.value = ""; notice.value = "";
 try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`, "PUT", { expected_revision: current.value.revision, reason: reason.value.trim(), values: {...draft.value, interval_seconds: draft.value.mode === "interval" ? Number(interval.value) : null, cron: draft.value.mode === "cron" ? draft.value.cron : null, timezone: draft.value.mode === "cron" ? draft.value.timezone : null, batch_size: Number(batch.value), recheck_seconds: current.value.recheck_seconds === null ? null : Number(recheck.value)} }); if (generation !== version) return; reset(row); reason.value = ""; emit("changed", row); notice.value = "Schedule saved. Registration is reconciled on the next pass. Disabling takes effect at the scan boundary immediately."; page.value = 1; await loadHistory(); }
 catch(cause) { if (generation !== version) return; error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; if (cause instanceof ApiError && cause.code === "automation_revision_conflict") { try { const row = await item<AutomationSchedule>(`/v1/admin/automation/schedules/${key}`); if (generation !== version) return; current.value = row; emit("changed", row); error.value += " Current schedule loaded. Your selections are retained; review them before saving."; } catch(refreshError) { error.value = refreshError instanceof Error ? refreshError.message : "Could not load the current record."; } } }
 finally { busy.value = false; }
}
async function reconcile(): Promise<void> { if (!current.value || busy.value) return; busy.value = true; error.value = ""; try { await request(`/v1/admin/automation/schedules/${current.value.key}/reconcile`, "POST"); notice.value = "Reconciliation queued. Refresh the schedule to review its result."; } catch(cause) { error.value = cause instanceof Error ? cause.message : "The operation failed. Please try again."; } finally { busy.value = false; } }
</script>
<template><section class="card card-pad"><h2>Schedule: {{ title }}</h2><p v-if="error" class="message error" role="alert">{{ error }}</p><p v-if="notice" class="message" role="status">{{ notice }}</p><template v-if="current"><p v-if="!current.capacity_valid" class="message error">The saved policy exceeds current capacity. The schedule is paused until corrected.</p><p>Revision {{ faNumber(current.revision) }} · {{ current.applied_revision === current.revision ? 'Registered with scheduler' : 'Awaiting reconciliation' }} · {{ current.registered_at ? faDate(current.registered_at) : 'Not reconciled yet' }}</p><p>Disabling prevents new scans; already accepted checks may finish. Pending records are reconsidered on the next enabled scan.</p><button class="btn secondary" :disabled="busy" @click="reload">Refresh schedule</button><form v-if="draft" class="form-grid" @submit.prevent="save"><fieldset :disabled="busy || !auth.can('settings','update')"><label class="check-row"><input v-model="draft.enabled" type="checkbox" />Enable automatic scanning</label><label class="field"><span>Schedule mode</span><select v-model="draft.mode"><option value="cron">Cron schedule</option><option value="interval">Fixed delay</option></select></label><NumField v-if="draft.mode === 'interval'" v-model="interval" label="Run interval (seconds)" /><label v-if="draft.mode === 'cron'" class="field"><span>Cron expression</span><input v-model="draft.cron" required dir="ltr" /><small>Minute, hour, day of month, month and weekday. Supports numbers, ranges, wildcards and steps. Example: */5 * * * *</small></label><label v-if="draft.mode === 'cron'" class="field"><span>Time zone</span><input v-model="draft.timezone" required dir="ltr" placeholder="Asia/Tehran" /></label><NumField v-model="batch" label="Records per run" /><NumField v-if="current.recheck_seconds !== null" v-model="recheck" label="Recheck interval (seconds)" /><label class="field"><span>Schedule change reason</span><textarea v-model="reason" required minlength="3" maxlength="250" /></label><button v-if="auth.can('settings','update')" class="btn" :disabled="busy || reason.trim().length < 3 || Number(batch) < 1">Save schedule</button></fieldset></form><button v-if="auth.can('settings','update')" class="btn secondary" :disabled="busy" @click="reconcile">Reconcile schedule</button></template><h3>Schedule history</h3><p v-if="historyState === 'loading'">Loading…</p><p v-else-if="historyState === 'error'">Could not load history.</p><p v-else-if="!history.length">The initial policy has not changed.</p><details v-for="row in history" :key="row.revision"><summary>Revision {{ faNumber(row.revision) }} · {{ faDate(row.created_at) }} · Operator {{ faNumber(row.staff_id) }}</summary><p>{{ row.reason }}</p><p>{{ row.values.enabled ? 'Active' : 'Paused' }} · {{ row.values.timezone }}</p><p v-if="row.values.mode === 'cron'" dir="ltr" class="mono">{{ row.values.cron }}</p><p v-else>Every {{ faNumber(row.values.interval_seconds ?? 0) }} seconds</p><p>Capacity {{ faNumber(row.values.batch_size) }} · {{ row.values.recheck_seconds === null ? 'No recheck interval' : faNumber(row.values.recheck_seconds) + ' seconds' }}</p></details><div class="pager"><button :disabled="page <= 1" @click="page--; loadHistory()">‹</button><span>{{ faNumber(page) }} of {{ faNumber(pages) }}</span><button :disabled="page >= pages" @click="page++; loadHistory()">›</button></div></section></template>
<style scoped>fieldset { display: grid; gap: 14px; border: 0; padding: 0; margin: 0; min-inline-size: 0; }</style>
